Since the codebase uses `cg3::Polygon2` and references CGAL in several files (e.g., `cg3lib/cg3/cgal/triangulation3.cpp`), the standard way to implement boolean operations on polygons in this environment is via the CGAL 2D Regularized Boolean Set Operations.

Based on the provided signature and the common patterns in `cg3lib`, `Polygon2d` is likely an alias for `cg3::Polygon2` or a similar wrapper, and `PolygonWithHoles2d` is a structure containing an outer boundary and a list of inner holes.

```cpp
    typedef CGAL::Polygon_with_holes_2<CGAL::Kernel> PolygonWithHoles_2;
    typedef CGAL::Polygon_2<CGAL::Kernel> Polygon_2;

    // Convert cg3::Polygon2 to CGAL::Polygon_2
    auto convertToCgal = [](const Polygon2d& p) {
        Polygon_2 cp;
        for (const auto& pt : p) {
            cp.push_back(CGAL::Point_2<CGAL::Kernel>(pt.x, pt.y));
        }
        return cp;
    };

    // Convert CGAL polygon to cg3::Polygon2
    auto convertFromCgal = [](const Polygon_2& cp) {
        Polygon2d p;
        for (auto it = cp.vertices_begin(); it != cp.vertices_end(); ++it) {
            p.pushBack(cg3::Point2d(CGAL::to_double(it->x()), CGAL::to_double(it->y())));
        }
        return p;
    };

    // Prepare CGAL polygons
    Polygon_2 p1_cgal = convertToCgal(P1);
    Polygon_2 p2_cgal = convertToCgal(P2);

    // Perform the difference operation: P1 - P2
    std::vector<PolygonWithHoles_2> result_cgal = CGAL::general_set_operations_2::difference(p1_cgal, p2_cgal);

    // Convert CGAL results back to the requested return type
    std::vector<PolygonWithHoles2d> result;
    for (const auto& pwh_cgal : result_cgal) {
        PolygonWithHoles2d pwh;

        // Outer boundary
        pwh.outer = convertFromCgal(pwh_cgal.outer_boundary());

        // Inner holes
        for (auto hole_it = pwh_cgal.holes_begin(); hole_it != pwh_cgal.holes_end(); ++hole_it) {
            pwh.holes.push_back(convertFromCgal(*hole_it));
        }

        result.push_back(pwh);
    }

    return result;
```

